'use strict';

// MODULES //

var tape = require( 'tape' );
var incrnanmmae = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrnanmmae, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if not provided a positive integer', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		-5.0,
		0.0,
		3.14,
		true,
		null,
		void 0,
		NaN,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			incrnanmmae( value );
		};
	}
});

tape( 'the function returns an accumulator function', function test( t ) {
	t.strictEqual( typeof incrnanmmae( 3 ), 'function', 'returns expected value' );
	t.end();
});

tape( 'the accumulator function computes a moving mean absolute error incrementally', function test( t ) {
	var expected;
	var actual;
	var data;
	var acc;
	var N;
	var i;

	data = [
		[ 2.0, 3.0 ],
		[ 3.0, -1.0 ],
		[ NaN, 1.0 ],
		[ 2.0, 5.0 ],
		[ 4.0, -4.0 ],
		[ 1.0, NaN ],
		[ 3.0, 0.0 ],
		[ NaN, NaN ],
		[ -4.0, 5.0 ]
	];
	N = data.length;

	acc = incrnanmmae( 3 );

	actual = [];
	for ( i = 0; i < N; i++ ) {
		actual.push( acc( data[i][0], data[i][1] ) );
	}
	expected = [ 1.0, 2.5, 2.5, 8.0/3.0, 5.0, 5.0, 14.0/3.0, 14.0/3.0, 20.0/3.0 ];

	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current mean absolute error', function test( t ) {
	var data;
	var acc;
	var i;

	data = [
		[ 2.0, 3.0 ],
		[ NaN, 1.0 ],
		[ 3.0, -5.0 ],
		[ 1.0, 10.0 ],
		[ 1.0, NaN ]
	];
	acc = incrnanmmae( 2 );
	for ( i = 0; i < data.length; i++ ) {
		acc( data[i][0], data[i][1] );
	}
	t.strictEqual( acc(), 8.5, 'returns expected value' );
	t.end();
});

tape( 'if data has yet to be provided, the accumulator function returns `null`', function test( t ) {
	var acc = incrnanmmae( 3 );
	t.strictEqual( acc(), null, 'returns expected value' );
	t.end();
});

tape( 'if only `NaN` values have been provided, the accumulator function returns `null`', function test( t ) {
	var acc = incrnanmmae( 3 );
	acc( NaN, 1.0 );
	acc( 1.0, NaN );
	acc( NaN, NaN );
	t.strictEqual( acc(), null, 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN`, the accumulator function ignores the provided values and returns the current mean absolute error', function test( t ) {
	var acc = incrnanmmae( 3 );
	t.strictEqual( acc( NaN, 1.0 ), null, 'returns expected value' );
	t.strictEqual( acc( 1.0, 3.0 ), 2.0, 'returns expected value' );
	t.strictEqual( acc( NaN, NaN ), 2.0, 'returns expected value' );
	t.strictEqual( acc( 4.0, NaN ), 2.0, 'returns expected value' );
	t.strictEqual( acc( 4.0, 0.0 ), 3.0, 'returns expected value' );
	t.strictEqual( acc( 1.0, NaN ), 3.0, 'returns expected value' );
	t.strictEqual( acc( 5.0, -1.0 ), 4.0, 'returns expected value' );
	t.strictEqual( acc( 0.0, 8.0 ), 6.0, 'returns expected value' );
	t.end();
});
